import { jsx as _jsx } from "react/jsx-runtime";
import { render, waitFor } from "@testing-library/react";
import { describe, it, expect } from "vitest";
import { DataGrid } from "@mui/x-data-grid";
import { testThemeConfigurations } from "./helpers";
import { RDSThemeProvider } from "../../../rdsThemeProvider";
describe("ThemedDataGrid Border Colors", () => {
    testThemeConfigurations.forEach(({ palettes, themeMap, themeName }) => {
        Object.entries(palettes).forEach(([mode, expectedColors]) => {
            it(`applies correct border colors in ${themeName} (${mode} mode)`, async () => {
                const columns = [
                    { field: "id", headerName: "ID" },
                    { field: "name", headerName: "Name" },
                    { field: "age", headerName: "Age" },
                    { field: "city", headerName: "City" },
                ];
                const rows = [
                    { age: 25, city: "New York", id: 1, name: "Alice" },
                    { age: 30, city: "London", id: 2, name: "Bob" },
                    { age: 22, city: "Berlin", id: 3, name: "Charlie" },
                    { age: 28, city: "Paris", id: 4, name: "David" },
                    { age: 35, city: "Tokyo", id: 5, name: "Eve" },
                ];
                const { container } = render(_jsx(RDSThemeProvider, { themeMap: themeMap, themeMode: mode, children: _jsx(DataGrid, { columns: columns, rows: rows }) }));
                const expectedBorderColor = expectedColors.components?.dataGrid?.border;
                await waitFor(() => {
                    const dataGridRoot = container.querySelector(".MuiDataGrid-root");
                    const footerContainer = container.querySelector(".MuiDataGrid-footerContainer");
                    expect(dataGridRoot).toHaveStyle(`border-color: ${expectedBorderColor}`);
                    expect(footerContainer).toHaveStyle(`border-top-color: ${expectedBorderColor}`);
                });
            });
        });
    });
});
